import type { ClassificationResult } from './classification';
import type { Evaluation, Metrics } from './metrics';

const pct = (value: number): string => `${(value * 100).toFixed(1)}%`;

function row(name: string, m: Metrics): string {
  return `| ${name} | ${pct(m.precision)} | ${pct(m.recall)} | ${m.f1.toFixed(3)} | ${m.truePositives} | ${m.falsePositives} | ${m.falseNegatives} |`;
}

export function renderMarkdown(
  evaluation: Evaluation,
  classification: ClassificationResult,
): string {
  const lines: string[] = [
    '# Detector evaluation',
    '',
    'This file is generated by `pnpm eval`, so edit the corpus or the detectors',
    'rather than this file.',
    '',
    `The test set has ${evaluation.sampleCount} samples. ${evaluation.positiveCount} contain secrets, ` +
      `and ${evaluation.negativeCount} contain text that looks like secrets but should not be flagged.`,
    '',
    'Each detector is scored on its own output, not through the full scanning',
    'pipeline, so its numbers are not affected by another detector winning an',
    'overlap.',
    '',
    '| Detector | Precision | Recall | F1 | TP | FP | FN |',
    '| --- | ---: | ---: | ---: | ---: | ---: | ---: |',
  ];

  for (const detector of evaluation.detectors) {
    lines.push(row(`\`${detector.detectorId}\``, detector));
  }

  lines.push(row('**Overall**', evaluation.overall), '');

  if (evaluation.falsePositives.length > 0) {
    lines.push('## False positives', '');
    for (const fp of evaluation.falsePositives) {
      lines.push(`- \`${fp.detectorId}\` on \`${fp.sampleId}\`: ${fp.label}, \`${fp.matched}\``);
    }
    lines.push('');
  }

  if (evaluation.misses.length > 0) {
    lines.push('## Misses', '');
    for (const miss of evaluation.misses) {
      lines.push(`- \`${miss.detectorId}\` on \`${miss.sampleId}\`: \`${miss.value}\``);
    }
    lines.push('');
  }

  lines.push(
    '## Context classification',
    '',
    `Accuracy: **${pct(classification.accuracy)}** (${classification.correct}/${classification.total}).`,
    '',
    'The scanner guesses what kind of text it is looking at, such as a log or a',
    'stack trace, and uses that to raise the severity of some findings. For',
    'example, an email address in a production log probably belongs to a real',
    'customer. Context never lowers a severity.',
    '',
    'This accuracy figure is weaker evidence than the detector numbers above. The',
    'same person wrote the classifier and labelled the samples, and there are',
    'fewer than fifty of them, so it mostly shows that the two agree. It is mainly',
    'useful in CI, where it catches changes that break classification.',
    '',
  );

  if (classification.misclassified.length > 0) {
    lines.push('Misclassified:', '');
    for (const m of classification.misclassified) {
      lines.push(`- \`${m.sampleId}\`: expected \`${m.expected}\`, got \`${m.actual}\``);
    }
    lines.push('');
  }

  return lines.join('\n');
}

export function renderConsole(
  evaluation: Evaluation,
  classification: ClassificationResult,
): string {
  const width = Math.max(...evaluation.detectors.map((d) => d.detectorId.length), 8);
  const lines = [
    `corpus: ${evaluation.sampleCount} samples (${evaluation.positiveCount} positive, ${evaluation.negativeCount} negative)`,
    '',
  ];

  for (const d of evaluation.detectors) {
    lines.push(
      `  ${d.detectorId.padEnd(width)}  P ${pct(d.precision).padStart(6)}  R ${pct(d.recall).padStart(6)}  F1 ${d.f1.toFixed(3)}`,
    );
  }

  lines.push(
    '',
    `  ${'overall'.padEnd(width)}  P ${pct(evaluation.overall.precision).padStart(6)}  R ${pct(evaluation.overall.recall).padStart(6)}  F1 ${evaluation.overall.f1.toFixed(3)}`,
    '',
    `  context classification: ${pct(classification.accuracy)} (${classification.correct}/${classification.total})`,
  );

  return lines.join('\n');
}
